Here's a sample C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string wordToSearch; // Word to search for
    string fileName; // Name of the file to read

    // Prompt user for input
    cout << "Enter the word to search for: ";
    cin >> wordToSearch;
    cout << "Enter the file name: ";
    cin >> fileName;

    // Open file for reading
    ifstream inputFile(fileName);
    if (!inputFile.is_open()) {
        cerr << "Error opening file: " << fileName << endl;
        return 1; // Exit with error code
    }

    // Read file line by line and count occurrences of word
    int count = 0;
    string line;
    while (getline(inputFile, line)) {
        // Convert line to lowercase to ignore case sensitivity
        transform(line.begin(), line.end(), line.begin(), ::tolower);
        // Count occurrences of word in line
        size_t pos = 0;
        while ((pos = line.find(wordToSearch, pos)) != string::npos) {
            count++;
            pos += wordToSearch.length();
        }
    }

    // Close file
    inputFile.close();

    // Output result
    cout << "The word '" << wordToSearch << "' appears " << count << " times in " << fileName << "." << endl;

    return 0; // Exit successfully
}
