class Deque:
    def __init__(self):
        self.front_stack = []
        self.rear_stack = []

    def is_empty(self):
        return len(self.front_stack) == 0 and len(self.rear_stack) == 0

    def push_front(self, data):
        self.front_stack.append(data)

    def push_rear(self, data):
