    def pop_front(self):
        if len(self.front_stack) == 0:
            if len(self.rear_stack) == 0:
                raise Exception("Deque is empty")
            while len(self.rear_stack) > 0:
                popped = self.rear_stack.pop()
                self.front_stack.append(popped)
            self.front_stack.pop()
        else:
            return self.front_stack.pop()

    def pop_rear(self):
        if len(self.rear_stack) == 0:
            if len(self.front_stack) == 0:
                raise Exception("Deque is empty")
            while len(self.front_stack) > 0:
                popped = self.front_stack.pop()
                self.rear_stack.append(popped)
            self.rear_stack.pop()
        else:
            return self.rear_stack.pop()

    def front(self):
        if len(self.front_stack) == 0:
            if len(self.rear_stack) == 0:
                raise Exception("Deque is empty")
            while len(self.rear_stack) > 0:
                popped = self.rear_stack.pop()
                self.front_stack.append(popped)
            return self.front_stack[-1]
        else:
